            heads = {slug(h) for h in re.findall(r'^#+\s+(.*)$', open(full).read(), re.M)}
            mark = "ok  " if anchor[1:] in heads else "BAD ANCHOR"
            print(f"{mark}          {f} -> {path}{anchor}")
        else:
            print(f"ok            {f} -> {path}")
PYEOF

