    return re.sub(r'\s+', '-', s)

bad = 0
for f in ('.vc-config.md', '.claude/.vc-config.md'):
    base = os.path.dirname(os.path.abspath(f))
    text = open(f).read()
    targets = set(re.findall(r'\]\(([^)#]+)(#[^)]*)?\)', text))
    targets |= set((m[0], m[1]) for m in re.findall(r'^\[\d+\]:\s*([^\s#]+)(#\S*)?$', text, re.M))
    for path, anchor in sorted(targets):
        if path.startswith('http'):
            continue
        full = os.path.normpath(os.path.join(base, path))
        if not os.path.exists(full):
            print(f"MISSING FILE  {f} -> {path}"); bad += 1; continue
        if anchor:
            heads = {slug(h) for h in re.findall(r'^#+\s+(.*)$', open(full).read(), re.M)}
